// Coerces the 11 form fields, builds identifiers, stamps batch metadata.
// All field values are preserved on the envelope so Phase 2+ can reuse them.
const f = $input.first().json;
const num = parseInt(f['Number of Questions'], 10);
const typeRaw = f['Question Type'];
const typeFolder = typeRaw === 'A&R' ? 'AR' : typeRaw;
const typeOut = typeFolder === 'AR' ? 'A&R' : typeFolder;

const batchId = Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 8);
const chapterCode = (f['Chapter Name'] || 'CHAPTER')
  .toUpperCase()
  .replace(/[^A-Z0-9]+/g, '_')
  .replace(/^_+|_+$/g, '')
  .slice(0, 24);

return [{
  json: {
    // --- echoed inputs (preserved verbatim for Phase 2+) ---
    board: f['Board'],
    class_name: f['Class'],
    chapter: f['Chapter Name'],
    source_type: f['Source Type'],
    question_type: typeOut,
    question_type_folder: typeFolder,
    difficulty: f['Difficulty'],
    number_of_questions: Number.isFinite(num) && num > 0 ? num : 10,
    include_visual_questions: (f['Include Visual Questions'] || 'NO').toUpperCase() === 'YES',
    language: f['Language'] || 'English',
    generate_explanation: (f['Generate Explanation'] || 'YES').toUpperCase() === 'YES',

    // --- derived identifiers ---
    chapter_code: chapterCode,
    batch_id: batchId,
    started_at: new Date().toISOString(),
    knowledge_file_name: `${chapterCode}_KNOWLEDGE.json`,

    // --- system prompt carried through (hidden form field) ---
    system_structurer: f['SYSTEM_STRUCTURER']
  },
  binary: $input.first().binary
}];

// Reads $json.text + PDF metadata from the previous node. Produces cleaned text
// and a small pdf_metadata object that goes into the final JSON.
const ctx = $('Normalize Input').first().json;
const raw = ($json.text || '').toString();
const meta = {
  num_pages: $json.numpages ?? $json.info?.NumPages ?? null,
  info:       $json.info ?? {},
  version:    $json.version ?? null,
  raw_chars:  raw.length
};

// 1) Remove explicit page-number markers and standalone numeric lines.
let t = raw.replace(/Page\s+\d+\s+of\s+\d+/gi, '');
t = t.split('\n').filter(l => !/^\s*\d{1,3}\s*$/.test(l)).join('\n');

// 2) Strip repeating headers/footers (lines appearing >5 times verbatim).
const freq = new Map();
t.split('\n').forEach(l => {
  const k = l.trim();
  if (k.length > 0 && k.length < 100) freq.set(k, (freq.get(k) || 0) + 1);
});
const boilerplate = new Set([...freq].filter(([, c]) => c > 5).map(([k]) => k));
t = t.split('\n').filter(l => !boilerplate.has(l.trim())).join('\n');

// 3) Strip the chapter title if it repeats on every page top.
const titleCandidates = [...freq]
  .filter(([k, c]) => c >= 3 && k.length < 80 && /^[A-Z][A-Za-z0-9 \-,'&()]+$/.test(k))
  .map(([k]) => k);
for (const tc of titleCandidates) {
  t = t.split('\n').filter(l => l.trim() !== tc || titleCandidates.indexOf(l.trim()) < 0 ? true : false).join('\n');
}

// 4) Fix OCR / PDF line-wrap artefacts.
t = t.replace(/-\n(\w)/g, '$1');             // de-hyphenate end-of-line hyphenation
t = t.replace(/([a-z,;])\n([a-z])/g, '$1 $2'); // join mid-sentence wraps
t = t.replace(/[ \t]{2,}/g, ' ');
t = t.replace(/\n{3,}/g, '\n\n');
t = t.replace(/[\u0000-\u0008\u000B-\u001F\u007F]/g, ' ');

// 5) Drop obvious URL / email tracker lines.
t = t.split('\n')
     .filter(l => !/^(https?:|www\.|email:)/i.test(l.trim()))
     .join('\n');

// 6) Repair common chemistry-notation breakages from PDF extraction:
//    - subscript digits stuck to the next token ('H 2 O' -> 'H2O')
//    - degree sign variants ('o C' -> '°C')
//    - arrow variants ('->'-> '→', '<->'-> '⇌')
t = t.replace(/\b([A-Z][a-z]?)\s+(\d)\b/g, '$1$2');
t = t.replace(/(\d)\s+([A-Z][a-z]?)\b/g, '$1$2');
t = t.replace(/(\d)\s*o\s*C\b/g, '$1°C');
t = t.replace(/<\s*-\s*>/g, '⇌').replace(/-\s*>/g, '→');

// 7) Collapse exact-duplicate adjacent paragraphs.
const paras = t.split(/\n\n+/);
const dedup = [];
for (const p of paras) { if (dedup[dedup.length - 1] !== p) dedup.push(p); }
const cleaned = dedup.join('\n\n').trim();

if (cleaned.length < 200) {
  throw new Error(`Cleaned text is suspiciously short (${cleaned.length} chars). Check the PDF — it may be scanned-only and need OCR.`);
}

return [{ json: { ...ctx, pdf_metadata: meta, cleaned_text: cleaned } }];

