// Robustly extracts the JSON object from the LLM response and attaches it to the envelope.
const ctx = $('Clean PDF Text').first().json;
const raw = $json.content?.[0]?.text || $json.message?.content?.[0]?.text || $json.text || '';
let cleaned = raw.trim().replace(/^```json\s*/i, '').replace(/```\s*$/i, '').trim();
// If the model prefixed prose, try to slice from the first '{' to the last '}'.
if (cleaned[0] !== '{') {
  const first = cleaned.indexOf('{');
  const last = cleaned.lastIndexOf('}');
  if (first === -1 || last === -1 || last <= first) {
    throw new Error('Structurer response did not contain a JSON object.');
  }
  cleaned = cleaned.slice(first, last + 1);
}
let structured;
try { structured = JSON.parse(cleaned); }
catch (e) { throw new Error('Structurer returned non-JSON: ' + e.message); }
return [{ json: { ...ctx, structured_knowledge: structured } }];

// Schema validation — no LLM. Fails loudly if the structurer omitted required arrays or returned wrong types.
const ctx = $json;
const k = ctx.structured_knowledge || {};

const REQUIRED_ARRAYS = [
  'topics', 'subtopics', 'definitions', 'formulae', 'laws', 'principles',
  'reactions', 'examples', 'tables', 'graph_references', 'diagram_references',
  'important_facts', 'exceptions', 'ncert_activities'
];

const issues = [];
if (typeof k.chapter_title !== 'string' || k.chapter_title.length === 0) {
  issues.push('chapter_title missing or not a string');
}
for (const key of REQUIRED_ARRAYS) {
  if (!Array.isArray(k[key])) issues.push(`${key} must be an array`);
}
// Sanity floor — a real CBSE chemistry chapter should yield more than a token of structure.
const totalEntries = REQUIRED_ARRAYS.reduce((s, key) => s + (Array.isArray(k[key]) ? k[key].length : 0), 0);
if (totalEntries < 8) {
  issues.push(`structured_knowledge looks too sparse (only ${totalEntries} entries across all arrays)`);
}

if (issues.length) {
  throw new Error('Knowledge object failed validation:\n - ' + issues.join('\n - '));
}

// Coerce missing optional keys to empty arrays for output stability.
for (const key of REQUIRED_ARRAYS) if (!Array.isArray(k[key])) k[key] = [];

return [{ json: { ...ctx, structured_knowledge: k, validation: { ok: true, total_entries: totalEntries } } }];

// Composes the final on-disk JSON exactly as Phase 1 specifies. All 11 form
// fields are preserved (under `form_inputs`) so Phase 2 can read them later.
const ctx = $json;
const k = ctx.structured_knowledge;

const payload = {
  board: ctx.board,
  class: ctx.class_name,
  chapter: ctx.chapter,
  source_type: ctx.source_type,

  pdf_metadata: ctx.pdf_metadata || {},

  topics:              k.topics              || [],
  subtopics:           k.subtopics           || [],
  definitions:         k.definitions         || [],
  formulae:            k.formulae            || [],
  laws:                k.laws                || [],
  principles:          k.principles          || [],
  reactions:           k.reactions           || [],
  examples:            k.examples            || [],
  tables:              k.tables              || [],
  graph_references:    k.graph_references    || [],
  diagram_references:  k.diagram_references  || [],
  important_facts:     k.important_facts     || [],
  exceptions:          k.exceptions          || [],
  ncert_activities:    k.ncert_activities    || [],

  clean_text: ctx.cleaned_text || '',

  // Echoed form values for Phase 2+ consumers.
  form_inputs: {
    board: ctx.board,
    class: ctx.class_name,
    chapter: ctx.chapter,
    source_type: ctx.source_type,
    question_type: ctx.question_type,
    difficulty: ctx.difficulty,
    number_of_questions: ctx.number_of_questions,
    include_visual_questions: ctx.include_visual_questions,
    language: ctx.language,
    generate_explanation: ctx.generate_explanation
  },

  meta: {
    phase: 1,
    schema_version: '1.0.0',
    chapter_code: ctx.chapter_code,
    batch_id: ctx.batch_id,
    generated_at: new Date().toISOString(),
    total_structured_entries: ctx.validation?.total_entries ?? null
  }
};

return [{ json: { ...ctx, final_payload: payload } }];

// Idempotently creates: Question Bank / CBSE / <Class> / <Chapter> / Knowledge Base
// using the Drive REST API with the OAuth credential bound on this node.
const ctx = $json;
const path = ['Question Bank', ctx.board, ctx.class_name, ctx.chapter, 'Knowledge Base'];

async function findOrCreate(name, parentId) {
  const q = encodeURIComponent(
    `name='${name.replace(/'/g, "\\'")}' and mimeType='application/vnd.google-apps.folder' and '${parentId}' in parents and trashed=false`
  );
  const list = await this.helpers.httpRequestWithAuthentication.call(this, 'googleDriveOAuth2Api', {
    method: 'GET',
    url: `https://www.googleapis.com/drive/v3/files?q=${q}&fields=files(id,name)`,
    json: true
  });
  if (list.files && list.files.length) return list.files[0].id;
  const created = await this.helpers.httpRequestWithAuthentication.call(this, 'googleDriveOAuth2Api', {
    method: 'POST',
    url: 'https://www.googleapis.com/drive/v3/files',
    body: { name, mimeType: 'application/vnd.google-apps.folder', parents: [parentId] },
    json: true
  });
  return created.id;
}

let parent = 'root';
const trail = [];
for (const seg of path) {
  parent = await findOrCreate.call(this, seg, parent);
  trail.push({ name: seg, id: parent });
}
return [{ json: { ...ctx, drive_folder_trail: trail, target_folder_id: parent } }];

const ctx = $json;
const buffer = Buffer.from(JSON.stringify(ctx.final_payload, null, 2), 'utf8');
return [{
  json: ctx,
  binary: {
    data: {
      data: buffer.toString('base64'),
      mimeType: 'application/json',
      fileName: ctx.knowledge_file_name
    }
  }
}];
